import{_ as e,o as a,c as r,a3 as o}from"./chunks/framework.DACwFHq9.js";const u=JSON.parse('{"title":"主页磁贴系统：未来演进方向备忘","description":"","frontmatter":{},"headers":[],"relativePath":"design/homepage-tile-system-future.md","filePath":"design/homepage-tile-system-future.md","lastUpdated":1786249556000}'),i={name:"design/homepage-tile-system-future.md"};function d(l,t,n,s,h,g){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="主页磁贴系统-未来演进方向备忘" tabindex="-1">主页磁贴系统：未来演进方向备忘 <a class="header-anchor" href="#主页磁贴系统-未来演进方向备忘" aria-label="Permalink to &quot;主页磁贴系统：未来演进方向备忘&quot;">​</a></h1><blockquote><p>状态：概念备忘 / 暂不实施</p><p>记录时间：2026-08-09</p><p>背景：从 <a href="./../Plan/homepage-portal-redesign-plan">主页重构计划</a> 中拆分，当前主页重构聚焦克制改动，磁贴系统作为更远期的方向单独存档。</p></blockquote><hr><h2 id="核心构想" tabindex="-1">核心构想 <a class="header-anchor" href="#核心构想" aria-label="Permalink to &quot;核心构想&quot;">​</a></h2><p>工具不再只是&quot;一个可点击的图标卡片&quot;，而是可以提供自己的<strong>磁贴组件（Widget）</strong>，在主页上展示实时内容或快捷操作。用户可以像 Windows 磁贴或 iOS 小组件那样，自由拖拽、调整尺寸、添加或删除磁贴。</p><hr><h2 id="磁贴尺寸规格-参考" tabindex="-1">磁贴尺寸规格（参考） <a class="header-anchor" href="#磁贴尺寸规格-参考" aria-label="Permalink to &quot;磁贴尺寸规格（参考）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>尺寸</th><th>格子占用</th><th>适用场景</th></tr></thead><tbody><tr><td>1×1</td><td>小</td><td>快速启动、单一状态指示</td></tr><tr><td>2×2</td><td>中</td><td>迷你对话框、缩略图预览</td></tr><tr><td>4×2</td><td>大</td><td>图表、多会话列表</td></tr></tbody></table><hr><h2 id="各工具磁贴设想" tabindex="-1">各工具磁贴设想 <a class="header-anchor" href="#各工具磁贴设想" aria-label="Permalink to &quot;各工具磁贴设想&quot;">​</a></h2><ul><li><strong>LLM Chat</strong>：展示最近的对话会话列表，或内嵌一个迷你快捷对话框。</li><li><strong>Media Generator</strong>：展示最近生成的图片缩略图网格。</li><li><strong>System Pulse</strong>（假设存在）：实时 CPU/内存占用的迷你折线图。</li><li><strong>Service Monitor</strong>（假设存在）：当前本地服务的健康状态指示灯。</li></ul><hr><h2 id="前置依赖" tabindex="-1">前置依赖 <a class="header-anchor" href="#前置依赖" aria-label="Permalink to &quot;前置依赖&quot;">​</a></h2><p>在正式实施磁贴系统前，需要先有：</p><ol><li><strong>工具插件化协议</strong>：工具需要能以标准接口导出自己的 Widget 组件，主页按需动态加载，而不是硬编码。</li><li><strong>布局持久化</strong>：拖拽结果、尺寸配置需要落盘到 <code>ConfigManager</code>，不能用 localStorage。</li><li><strong>主页配置体系</strong>：当前主页重构完成后，配置结构（推荐位、最近使用）迁移到 <code>ConfigManager</code> 后，再在此基础上扩展磁贴布局配置。</li></ol><hr><h2 id="与当前重构的关系" tabindex="-1">与当前重构的关系 <a class="header-anchor" href="#与当前重构的关系" aria-label="Permalink to &quot;与当前重构的关系&quot;">​</a></h2><p>当前正在实施的主页重构（快速入口横条 + 垂直分类侧边栏）<strong>不需要</strong>为磁贴系统预留任何代码结构。等到需要做磁贴时再按实际情况设计，不要提前抽象。</p>',18)])])}const p=e(i,[["render",d]]);export{u as __pageData,p as default};
